Safe String Handling.code:
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Use snprintf — always null-terminates, never overflows
void safe_build_path(char *buf, size_t size,
    const char *dir, const char *file) {
    snprintf(buf, size, "%s/%s", dir, file);
}

// Self-contained safe string type
struct SafeStr {
    char *data;
    size_t len;
    size_t cap;
};

struct SafeStr *ss_new(size_t cap) {
    struct SafeStr *s = malloc(sizeof(*s));
    s->data = malloc(cap);
    s->data[0] = '\0';
    s->len = 0;
    s->cap = cap;
    return s;
}

void ss_append(struct SafeStr *s, const char *src) {
    size_t add = strlen(src);
    if (s->len + add >= s->cap) return;  // prevent overflow
    memcpy(s->data + s->len, src, add + 1);
    s->len += add;
}

void ss_free(struct SafeStr *s) {
    free(s->data);
    free(s);
}

Pointer Pitfalls.code:
#include <stdlib.h>
#include <stdio.h>

void pointer_pitfalls() {
    // 1. Uninitialized pointer
    int *p1;  // garbage address
    // *p1 = 42;  // CRASH: undefined behavior

    // 2. Dangling after free
    int *p2 = malloc(sizeof(int));
    free(p2);
    p2 = NULL;  // BEST PRACTICE: null after free

    // 3. Null dereference
    int *p3 = NULL;
    if (p3 != NULL) *p3 = 42;  // always check

    // 4. Past-bounds arithmetic
    int arr[5];
    int *p4 = arr;
    // *(p4 + 10) = 99;  // UB: writing past end

    // 5. Alignment violation
    void *raw = malloc(16);
    char *misaligned = (char *)raw + 1;
