std::counting_semaphore.code:
#include <semaphore>

std::counting_semaphore<10> sem(0); // max 10, initial 0
std::vector<int> buffer;
std::mutex mtx;

void producer() {
    for (int i = 0; i < 20; ++i) {
        {
            std::lock_guard lk(mtx);
            buffer.push_back(i);
        }
        sem.release(); // signal consumer
    }
}

void consumer() {
    for (int i = 0; i < 20; ++i) {
        sem.acquire(); // wait for data
        std::lock_guard lk(mtx);
        int val = buffer.back();
        buffer.pop_back();
        std::cout << "got: " << val << std::endl;
    }
}

