struct IsPointer {
    static constexpr bool value = false;
};
template<typename T>
struct IsPointer<T*> {
    static constexpr bool value = true;
};

int main() {
    static_assert(std::is_integral_v<int>);
    static_assert(!std::is_floating_point_v<int>);
    static_assert(std::is_same_v<int, std::decay_t<int&>>);
    static_assert(IsPointer<int*>::value);

    std::cout << category(42) << std::endl;     // integral
    std::cout << category(3.14) << std::endl;    // float
    std::cout << category("hi") << std::endl;    // other

    // SFINAE with enable_if
    template<typename T>
