#include <algorithm>
#include <execution>
#include <vector>
#include <numeric>
#include <iostream>

int main() {
    std::vector<int> v(10'000'000);
    std::iota(v.begin(), v.end(), 0);

    // sequential (default, no overhead)
    std::sort(std::execution::seq, v.begin(), v.end());

    // parallel with threads
    std::sort(std::execution::par, v.begin(), v.end());

    // parallel + vectorized (SIMD instructions)
    std::transform(std::execution::par_unseq,
        v.begin(), v.end(), v.begin(),
        [](int x) { return x * x; });

    // parallel reduce vs accumulate
    long sum = std::reduce(std::execution::par,
        v.begin(), v.end(), 0L);

    std::cout << "sum: " << sum << std::endl;

    // need -ltbb or compiler-specific parallel backend
    // return 0;
}

