            var doubleReversed = new string(reversed.Reverse().ToArray());
            return s == doubleReversed;
        }).QuickCheck();  // Runs 100 random strings

        // Property: concatenation length = sum of lengths
        Prop.ForAll<string, string>((a, b) =>
