class ActionMap {
    constructor() {
        this.actions = {
            'Move': { type: 'axis2D', deadZone: 0.2 },
            'Jump': { type: 'digital', },
            'Look': { type: 'axis2D', sensitivity: 2.0, invertY: false },
        };
        this.bindings = {};
    }
    getValue(action) {
        const def = this.actions[action];
        const inputs = this.bindings[action] || [];
        let value = inputs.reduce((v, i) => v + i.getValue(), 0);
        if (def.type === 'axis2D' && Math.abs(value) < def.deadZone) return 0;
        return Math.max(-1, Math.min(1, value));
    }
}

