// Voronoi (Worley noise) texture
vec3 voronoi(vec2 uv) {
    vec2 i = floor(uv);
    vec2 f = fract(uv);
    float minDist = 1.0;
    vec2 minPoint = vec2(0);
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = hash2(i + neighbor);
            float dist = length(neighbor + point - f);
            if (dist < minDist) {
                minDist = dist;
                minPoint = point;
            }
        }
    }
    return vec3(minDist);
}
// Marble: sin(x * freq + noise(x,y))

