class Profiler {
    constructor() {
        this.samples = new Map();
        this.stacks = [];
    }
    begin(name) {
        this.stacks.push({ name, start: performance.now() });
    }
    end() {
        const frame = this.stacks.pop();
        const elapsed = performance.now() - frame.start;
        if (!this.samples.has(frame.name)) this.samples.set(frame.name, []);
        this.samples.get(frame.name).push(elapsed);
    }
    report() {
        for (const [name, times] of this.samples) {
            const avg = times.reduce((a, b) => a + b, 0) / times.length;
            const max = Math.max(...times);
            console.log(`${name}: avg=${avg.toFixed(2)}ms max=${max.toFixed(2)}ms`);
