class AutoSaveManager {
    constructor(saveManager, intervalMs = 300000) {
        this.saveManager = saveManager;
        this.interval = intervalMs;
        this.lastSave = Date.now();
        this.slots = ['autosave_1', 'autosave_2', 'autosave_3'];
        this.currentSlot = 0;
    }
    update(gameState) {
        if (gameState.inCombat) return;
        if (Date.now() - this.lastSave > this.interval) {
            this.trigger(gameState);
        }
    }
    async trigger(gameState) {
        const slot = this.slots[this.currentSlot % this.slots.length];
        await this.saveManager.save(slot, gameState);
        this.currentSlot++;
        this.lastSave = Date.now();
    }
}

