using UnityEngine;
using UnityEngine.AI;

public class AIController : MonoBehaviour {
    private NavMeshAgent agent;
    public Transform target;

    void Start() {
        agent = GetComponent<NavMeshAgent>();
        agent.speed = 5f;
        agent.stoppingDistance = 1.5f;
        agent.autoBraking = true;
        // agent.radius = 0.5f;   // Agent size for avoidance
        // agent.height = 2.0f;
    }

    void Update() {
        if (target) {
            agent.SetDestination(target.position);
        }

        // Check path status
        if (agent.pathStatus == NavMeshPathStatus.PathPartial) {
            Debug.Log("Cannot reach target");
        }
    }

    // OffMeshLink: manual traversal
    IEnumerator JumpOverGap() {
        agent.isStopped = true;
        // Animate jump across link
        yield return new WaitForSeconds(0.5f);
        agent.isStopped = false;
        agent.CompleteOffMeshLink();
    }

    // Bake at runtime
    void BakeDynamicArea(Bounds area) {
        var surface = FindObjectOfType<NavMeshSurface>();
        surface.Bake();  // Expensive; use async
    }
}

