Pagination.code:
type Query {
  users(first: Int!, after: String): UserConnection!
}

type UserConnection {
  edges: [UserEdge!]!
  pageInfo: PageInfo!
  totalCount: Int!
}

type UserEdge {
  node: User!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  hasPreviousPage: Boolean!
  startCursor: String
  endCursor: String
}

// Resolver
users: async (_, { first, after }, { db }) => {
  const afterId = after ? Buffer.from(after, 'base64').toString() : null;

  const users = await db.users.findAll({
    limit: first + 1,
    where: afterId ? { id: { [Op.gt]: afterId } } : {},
    order: [['id', 'ASC']]
  });

  const hasNextPage = users.length > first;
  const nodes = hasNextPage ? users.slice(0, first) : users;

  return {
    edges: nodes.map(user => ({
      node: user,
      cursor: Buffer.from(String(user.id)).toString('base64')
    })),
    pageInfo: {
      hasNextPage,
      hasPreviousPage: !!after,
      startCursor: nodes[0] && Buffer.from(String(nodes[0].id)).toString('base64'),
      endCursor: nodes[nodes.length - 1] && Buffer.from(String(nodes[nodes.length - 1].id)).toString('base64')
    },
    totalCount: await db.users.count()
  };
}

What is Java.code:
// Java — platform-independent, object-oriented
public class HelloWorld {
    public static void main(String[] args) {
        System.out.println("Hello, Java!");
    }
}

// Compile: javac HelloWorld.java  → produces HelloWorld.class bytecode
// Run:     java HelloWorld         → JVM interprets bytecode

// Key characteristics:
// - Statically typed: all variables have a declared type
// - Garbage collected: memory managed automatically
// - JVM-based: bytecode runs anywhere a JVM exists

JDK vs JRE vs JVM.code:
// Check installed versions from terminal:
// java -version       → shows JRE/JVM version
// javac -version      → shows JDK compiler version
// javac HelloWorld.java  → JDK compiles source → .class bytecode
// java HelloWorld         → JRE executes bytecode

// JDK = JRE + dev tools (compiler, debugger, profiler)
// JRE = JVM + core libraries
