Transactions.code:
const session = client.startSession();

try {
  const result = await session.withTransaction(async () => {
    const orders = client.db('sales').collection('orders');
    const inventory = client.db('sales').collection('inventory');

    const order = await orders.insertOne({
      userId: 'ABC',
      items: [{ sku: 'LAPTOP', qty: 1, price: 999 }],
      total: 999
    }, { session });

    const update = await inventory.updateOne(
      { sku: 'LAPTOP', qty: { $gte: 1 } },
      { $inc: { qty: -1 } },
      { session }
    );

    if (update.modifiedCount === 0) {
      throw new Error('Insufficient inventory');
    }

    return order.insertedId;
  }, {
    readConcern: { level: 'majority' },
    writeConcern: { w: 'majority' },
    readPreference: 'primary'
  });
} catch (err) {
  console.error('Transaction failed:', err);
} finally {
  await session.endSession();
}

