CREATE OR REPLACE FUNCTION process_orders()
RETURNS VOID AS $$
DECLARE
  v_count INT := 0;
  v_order orders%ROWTYPE;
  cur CURSOR FOR SELECT * FROM orders WHERE status = 'pending';
BEGIN
  OPEN cur;
  LOOP
    FETCH cur INTO v_order;
    EXIT WHEN NOT FOUND;
    v_count := v_count + 1;
    -- process v_order
  END LOOP;
  CLOSE cur;
  RAISE NOTICE 'Processed % orders', v_count;
END;
$$ LANGUAGE plpgsql;

-- Simpler: FOR loop
FOR rec IN SELECT * FROM orders WHERE status = 'pending' LOOP
  -- process
END LOOP;

PL/pgSQL Exception Handling.code:
CREATE OR REPLACE FUNCTION safe_insert(p_id INT, p_name TEXT)
RETURNS TEXT AS $$
BEGIN
  INSERT INTO users (id, name) VALUES (p_id, p_name);
  RETURN 'OK';
EXCEPTION
  WHEN unique_violation THEN
    RETURN 'Duplicate ID';
  WHEN not_null_violation THEN
    RETURN 'Name is required';
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_msg = MESSAGE_TEXT,
      v_detail = PG_EXCEPTION_DETAIL;
    RAISE WARNING 'Unexpected error: %', v_msg;
    RETURN 'Error';
END;
$$ LANGUAGE plpgsql;

