Triggers (BEFORE/AFTER/INSTEAD OF).code:
CREATE OR REPLACE FUNCTION validate_salary()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.salary < 0 THEN
    RAISE EXCEPTION 'Salary cannot be negative';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER before_salary_insert
BEFORE INSERT ON employees
FOR EACH ROW EXECUTE FUNCTION validate_salary();

-- INSTEAD OF trigger (on view)
CREATE VIEW active_users AS SELECT * FROM users WHERE active = TRUE;

CREATE OR REPLACE FUNCTION instead_of_delete()
RETURNS TRIGGER AS $$
BEGIN
  UPDATE users SET active = FALSE WHERE id = OLD.id;
  RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER soft_delete_trigger
INSTEAD OF DELETE ON active_users
FOR EACH ROW EXECUTE FUNCTION instead_of_delete();

Trigger Functions (TG_OP, TG_TABLE_NAME).code:
CREATE OR REPLACE FUNCTION universal_audit()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO audit_log (
    table_name, operation, old_data, new_data, changed_by, changed_at
  ) VALUES (
    TG_TABLE_NAME,
    TG_OP,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END,
    current_user,
    NOW()
  );
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$ LANGUAGE plpgsql;

-- Apply to multiple tables
CREATE TRIGGER audit_users AFTER INSERT OR UPDATE OR DELETE ON users
FOR EACH ROW EXECUTE FUNCTION universal_audit();

