PL/pgSQL Profiling & Optimization.code:
-- auto_explain (postgresql.conf)
# shared_preload_libraries = 'auto_explain'
# auto_explain.log_min_duration = '1s'
# auto_explain.log_analyze = on
# auto_explain.log_nested_statements = on  -- includes PL/pgSQL internals

-- Bad: row-by-row processing (slow)
CREATE OR REPLACE FUNCTION slow_update() RETURNS VOID AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN SELECT * FROM orders WHERE status = 'pending' LOOP
    UPDATE orders SET status = 'processed' WHERE id = r.id;
  END LOOP;
END;
$$ LANGUAGE plpgsql;

