from openai import OpenAI
import os
import time
from functools import wraps

client = OpenAI(api_key=os.environ.get('OPENAI_API_KEY'))

def retry_with_backoff(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_retries - 1:
                        raise
                    time.sleep(2 ** attempt)
            return None
        return wrapper
    return decorator

@retry_with_backoff()
def stream_response(system_prompt, user_prompt):
    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': user_prompt}
        ],
        stream=True,
        temperature=0
    )

    for chunk in response:
        content = chunk.choices[0].delta.content or ''
        if content:
            print(content, end='', flush=True)  # stream to console

# Structured output (JSON mode)
def structured_extract(text):
    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[
            {'role': 'system', 'content': 'Extract entities as JSON.'},
            {'role': 'user', 'content': text}
        ],
        response_format={'type': 'json_object'}
    )
    return json.loads(response.choices[0].message.content)

Prompt Caching & Optimization.code:
from functools import lru_cache
from openai import OpenAI
import hashlib
import json
import os
import time

client = OpenAI(api_key=os.environ.get('OPENAI_API_KEY'))

# Exact match cache
class PromptCache:
    def __init__(self, maxsize=100):
        self._cache = {}
        self._maxsize = maxsize

    def _make_key(self, messages):
        return hashlib.sha256(json.dumps(messages, sort_keys=True).encode()).hexdigest()

    def get(self, messages):
        key = self._make_key(messages)
        return self._cache.get(key)

    def set(self, messages, response):
        key = self._make_key(messages)
        if len(self._cache) >= self._maxsize:
            self._cache.pop(next(iter(self._cache)))
        self._cache[key] = response

cache = PromptCache()

def cached_completion(messages):
    if cached := cache.get(messages):
        print('Cache hit!')
        return cached

    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=messages
    )
    result = response.choices[0].message.content
    cache.set(messages, result)
    return result

# Prompt compression (reduce token count)
def compress_prompt(text, target_ratio=0.5):
    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[
            {'role': 'system', 'content': f'Compress this text to {target_ratio:.0%} of original while preserving key information.'},
            {'role': 'user', 'content': text}
        ]
    )
    return response.choices[0].message.content

