indirect enum BinaryTree<T> {
    case leaf(T)
    case node(left: BinaryTree<T>, right: BinaryTree<T>)
}

let tree = BinaryTree.node(
    left: .leaf(1),
    right: .node(left: .leaf(2), right: .leaf(3))
)

func depth<T>(of tree: BinaryTree<T>) -> Int {
    switch tree {
    case .leaf:
        return 0
    case let .node(left, right):
        return 1 + max(depth(of: left), depth(of: right))
    }
}
