func processFile(_ name: String) throws {
    print("Opening \(name)...")
    defer {
        print("Closing \(name)...")
    }

    guard !name.isEmpty else { return }
    defer { print("Processing done") }

    print("Processing...")
    // defers execute in reverse order:
    // "Processing done" then "Closing ..."
}

