Protocol Extensions & Defaults.code:
protocol StringRepresentable {
    var stringValue: String { get }
}

// Default implementation
extension StringRepresentable {
    var stringValue: String { "\(Self.self)" }
}

// Constrained extension: only for arrays where Element conforms
extension StringRepresentable where Self: Collection, Self.Element: StringRepresentable {
    var stringValue: String {
        "[" + map { $0.stringValue }.joined(separator: ", ") + "]"
    }
}

struct Person: StringRepresentable {
    var name: String
}

struct Group: StringRepresentable {
    var members: [Person]
}

extension Group: Collection {
    typealias Element = Person
    var startIndex: Int { members.startIndex }
    var endIndex: Int { members.endIndex }
    subscript(position: Int) -> Person { members[position] }
    func index(after i: Int) -> Int { i + 1 }
}

let p = Person(name: "Alice")
let g = Group(members: [p, Person(name: "Bob")])
print(p.stringValue)  // Person
print(g.stringValue)  // [Person, Person]

