import { z } from 'zod';
import OpenAI from 'openai';
import { zodResponseFormat } from 'openai/helpers/zod';

const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// Complex nested schema
const SupportTicketSchema = z.object({
  priority: z.enum(['low', 'medium', 'high', 'critical']),
  category: z.enum(['bug', 'feature', 'question', 'billing']),
  summary: z.string().min(10).max(200),
  stepsToReproduce: z.array(z.string()).optional(),
  metadata: z.object({
    userId: z.string(),
    browser: z.string().optional(),
    os: z.string().optional(),
  }),
});

type SupportTicket = z.infer<typeof SupportTicketSchema>;

async function parseSupportTicket(text: string): Promise<SupportTicket> {
  const response = await client.beta.chat.completions.parse({
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: 'Extract support ticket details as structured data.' },
      { role: 'user', content: text },
    ],
    response_format: zodResponseFormat(SupportTicketSchema, 'ticket'),
  });

  return response.choices[0]?.message?.parsed as SupportTicket;
}

// Discriminated union for conditional extraction
const PaymentEvent = z.discriminatedUnion('type', [
  z.object({ type: z.literal('completed'), amount: z.number(), currency: z.string() }),
  z.object({ type: z.literal('failed'), reason: z.string(), code: z.string() }),
  z.object({ type: z.literal('refunded'), amount: z.number(), reason: z.string() }),
]);

type PaymentEvent = z.infer<typeof PaymentEvent>;

async function parseEvent(text: string): Promise<PaymentEvent> {
  const response = await client.beta.chat.completions.parse({
    model: 'gpt-4o-mini',
    messages: [{ role: 'user', content: text }],
    response_format: zodResponseFormat(PaymentEvent, 'event'),
  });
  return response.choices[0]?.message?.parsed as PaymentEvent;
}

// Custom refinement
