  issues: z.array(z.object({
    severity: z.enum(['error', 'warning', 'info']),
    line: z.number().int().positive(),
    message: z.string(),
  })).refine((issues) => issues.length <= 10, {
    message: 'Max 10 issues per review',
  }),
  overallScore: z.number().min(0).max(100),
