using UnityEngine;

public class TerrainController : MonoBehaviour
{
    public Terrain terrain;
    public TerrainData terrainData;
    public Material terrainMaterial;

    void Start()
    {
        terrain = GetComponent<Terrain>();
        terrainData = terrain.terrainData;

        // Terrain settings
        terrain.heightmapPixelError = 5;
        terrain.basemapDistance = 500;
        terrain.detailObjectDensity = 0.5f;
        terrain.treeDistance = 500;

        // Add tree
        var tree = new TreePrototype();
        tree.prefab = treePrefab;
        terrainData.treePrototypes = new TreePrototype[] { tree };

        // Place trees
        var instances = new TreeInstance[10];
        for (int i = 0; i < 10; i++)
        {
            instances[i] = new TreeInstance
            {
                position = new Vector3(Random.Range(0f, 1f), 0, Random.Range(0f, 1f)),
                widthScale = Random.Range(0.8f, 1.2f),
                heightScale = Random.Range(0.8f, 1.2f),
                prototypeIndex = 0
            };
        }
        terrainData.treeInstances = instances;

        // Paint terrain texture
        var splat = new SplatPrototype[1];
        splat[0] = new SplatPrototype
        {
            texture = groundTexture,
            tileSize = new Vector2(10, 10)
        };
        terrainData.splatPrototypes = splat;

        // Modify height
        float[,] heights = terrainData.GetHeights(0, 0, terrainData.heightmapResolution, terrainData.heightmapResolution);
        for (int x = 0; x < terrainData.heightmapResolution; x++)
            for (int y = 0; y < terrainData.heightmapResolution; y++)
                heights[x, y] = Mathf.PerlinNoise(x * 0.01f, y * 0.01f) * 0.3f;
        terrainData.SetHeights(0, 0, heights);
    }

    void OnDrawGizmosSelected()
    {
        // Show terrain bounds
        Gizmos.DrawWireCube(terrain.transform.position + terrainData.bounds.center, terrainData.bounds.size);
    }
}

